function layoutWord(word: string) {
  const segs: Array<[Pt, Pt]> = [];
  const paths: Pt[][] = [];
  let x = 0;
  const chars = word.toUpperCase().split("");
  chars.forEach((ch, i) => {
    if (ch === " ") {
      x += 2.6;
      return;
    }
    const g = GLYPHS[ch];
    if (!g) return;
    for (const stroke of g.strokes) {
      const moved = stroke.map(([px, py]) => [px + x, py] as Pt);
      paths.push(moved);
      for (let k = 1; k < moved.length; k++)
        segs.push([moved[k - 1], moved[k]]);
    }
    x += g.w + (i < chars.length - 1 ? GAP : 0);
  });
  return { segs, paths, width: Math.max(1, x) };
}

function segDist(px: number, py: number, [a, b]: [Pt, Pt]) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const l2 = dx * dx + dy * dy;
  const k =
    l2 === 0
      ? 0
      : Math.max(0, Math.min(1, ((px - a[0]) * dx + (py - a[1]) * dy) / l2));
  const ex = px - (a[0] + k * dx);
  const ey = py - (a[1] + k * dy);
  return Math.sqrt(ex * ex + ey * ey);
}

const smooth = (a: number, b: number, x: number) => {
  const k = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return k * k * (3 - 2 * k);
};

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function LineReliefBase(props: LineReliefProps) {
  const {
    word = "LAUNCH",
    count = LINES,
    accent = "#3B5BFD",
    ink,
    background,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    lineReliefTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const enterEl = tl.get("enter");
  const spreadEl = tl.get("spread");
  const riseEl = tl.get("rise");
  const settleEl = tl.get("settle");
  const revealEl = tl.get("reveal");
  const u = height / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const sky =
    background === undefined
      ? p.sky.map(
          ([o, c, k]) =>
            [o, c === "accent" ? mix(p.sky[1][1], accent, k) : c] as const,
        )
      : ([
          [0, background],
          [1, background],
        ] as const);
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const left = width * 0.08;
  const right = width * 0.92;
  const top = height * 0.2;
  const bottom = height * 0.84;
  const fieldW = right - left;
  const step = (bottom - top) / (count - 1);

  const glyphs = useMemo(() => layoutWord(word), [word]);
  const unit = Math.min((fieldW * 0.8) / glyphs.width, (height * 0.3) / 6);
  const wordX = left + (fieldW - glyphs.width * unit) / 2;
  const wordY = (top + bottom) / 2 - 3 * unit + step * 0.5;
  const lift = step * 2.5;

  const field = useMemo(() => {
    const rows: number[][] = [];
    for (let j = 0; j < count; j++) {
      const gy = (top + j * step - wordY) / unit;
      const row: number[] = [];
      for (let i = 0; i <= SAMPLES; i++) {
        const gx = (left + (fieldW * i) / SAMPLES - wordX) / unit;
        let d = Number.POSITIVE_INFINITY;
        if (gx > -2 && gx < glyphs.width + 2 && gy > -2 && gy < 8) {
          for (const s of glyphs.segs) d = Math.min(d, segDist(gx, gy, s));
        }
        row.push(1 - smooth(0.05, 0.95, d));
      }
      rows.push(row);
    }
    return rows;
  }, [glyphs, left, fieldW, top, step, unit, wordX, wordY, count]);

  const settle = interpolate(t, [settleEl.start, settleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const reveal = interpolate(t, [revealEl.start, revealEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const enter = interpolate(t, [enterEl.start, enterEl.end], [0.45, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const sec = t / 30;

  const lines = field.map((row, j) => {
    const base = top + j * step;
    const ring = Math.abs(j - (count - 1) / 2);
    const reachAt = spreadEl.start + ring * spreadEl.beat("step");
    const reach = interpolate(
      t,
      [reachAt, reachAt + spreadEl.beat("reach")],
      [0.2, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    let d = "";
    let hi = "";
    let inHi = false;
    let maxLift = 0;
    for (let i = 0; i <= SAMPLES; i++) {
      const xn = i / SAMPLES;
      if (xn > reach + 0.0001) continue;
      const grow = interpolate(
        t,
        [
          riseEl.start + xn * riseEl.beat("sweep"),
          riseEl.start + riseEl.beat("grow") + xn * riseEl.beat("sweep"),
        ],
        [0, 1],
        {
          ...CLAMP,
          easing: EASE_RISE,
        },
      );
      const h = row[i] * grow * (1 - settle);
      maxLift = Math.max(maxLift, h);
      const drift =
        1.2 *
          u *
          Math.sin(xn * 19 + sec * 1.6 + j * 0.7 + hash(j) * 6) *
          (1 - settle) +
        0.8 * u * Math.sin(xn * 47 - sec * 2.3 + j * 1.3);
      const y = base - lift * h - drift * (1 - h);
      const pt = `${(left + xn * fieldW).toFixed(2)} ${y.toFixed(2)}`;
      d += `${d ? "L" : "M"}${pt}`;
      const on = row[i] > 0.015;
      if (on) hi += `${inHi ? "L" : "M"}${pt}`;
      inHi = on;
    }
    const x0 = left;
    const x1 =
      left +
      Math.min(1, Math.floor(reach * SAMPLES + 0.0001) / SAMPLES) * fieldW;
    return {
      d,
      fill: `${d} L${x1.toFixed(2)} ${(base + step * 0.6).toFixed(2)} L${x0.toFixed(2)} ${(base + step * 0.6).toFixed(2)} Z`,
      hi,
      maxLift,
      j,
    };
  });

  const wordPaths = glyphs.paths.map((path) =>
    path
      .map(
        ([gx, gy], k) =>
          `${k ? "L" : "M"}${(wordX + gx * unit).toFixed(2)} ${(wordY + gy * unit).toFixed(2)}`,
      )
      .join(" "),
  );
  const strokeW = STROKE * unit;
  const wordShift = (1 - reveal) * -lift * 0.45;
  // The sky shares one SVG with the lines, so the field scales as an SVG
  // transform rather than a ScaleLayer; the line fills then need the sky
  // gradient stretched back so they still match the sky behind them.
  const scaleT =
    scale === 1
      ? undefined
      : `translate(${width / 2} ${height / 2}) scale(${scale}) translate(${-width / 2} ${-height / 2})`;
  const occlude = scale === 1 ? `url(#${id}d)` : `url(#${id}f)`;

  return (
    <AbsoluteFill
      style={{
        background:
          background === undefined
            ? p.bg
            : background === "transparent"
              ? undefined
              : background,
        overflow: "hidden",
      }}
    >
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={`${id}d`}
            gradientUnits="userSpaceOnUse"
            x1={0}
            y1={0}
            x2={0}
            y2={height}
          >
            {sky.map(([o, c]) => (
              <stop key={o} offset={o} stopColor={c} />
            ))}
          </linearGradient>
          {scaleT ? (
            <linearGradient
              id={`${id}f`}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={height / 2 - height / (2 * scale)}
              x2={0}
              y2={height / 2 + height / (2 * scale)}
            >
              {sky.map(([o, c]) => (
                <stop key={o} offset={o} stopColor={c} />
              ))}
            </linearGradient>
          ) : null}
          <linearGradient id={`${id}e`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor="#fff" stopOpacity={0} />
            <stop offset="0.07" stopColor="#fff" stopOpacity={1} />
            <stop offset="0.93" stopColor="#fff" stopOpacity={1} />
            <stop offset="1" stopColor="#fff" stopOpacity={0} />
          </linearGradient>
          <mask
            id={`${id}m`}
            maskUnits="userSpaceOnUse"
            x={0}
            y={0}
            width={width}
            height={height}
          >
            <rect
              x={left}
              y={0}
              width={fieldW}
              height={height}
              fill={`url(#${id}e)`}
            />
            <g transform={`translate(0 ${wordShift})`} opacity={reveal}>
              {wordPaths.map((d) => (
                <path
                  key={d}
                  d={d}
                  fill="none"
                  stroke="#000"
                  strokeWidth={strokeW + step * 1.3}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              ))}
            </g>
          </mask>
        </defs>
        <rect width={width} height={height} fill={`url(#${id}d)`} />
        <g mask={`url(#${id}m)`} opacity={enter} transform={scaleT}>
          {lines.map((l) => (
            <g key={l.j}>
              <path d={l.fill} fill={occlude} />
              <path
                d={l.d}
                fill="none"
                stroke={fg}
                strokeOpacity={p.line}
                strokeWidth={1.3 * u}
                strokeLinejoin="round"
              />
              {l.hi && l.maxLift > 0.001 && (
                <path
                  d={l.hi}
                  fill="none"
                  stroke={fg}
                  strokeOpacity={
                    (p.lift - p.line) * Math.min(1, l.maxLift * 1.4)
                  }
                  strokeWidth={1.3 * u}
                  strokeLinejoin="round"
                />
              )}
            </g>
          ))}
        </g>
        <g
          transform={`${scaleT ? `${scaleT} ` : ""}translate(0 ${wordShift})`}
          opacity={reveal}
          style={{ filter: `blur(${(1 - reveal) * 6 * u}px)` }}
        >
          {wordPaths.map((d) => (
            <path
              key={d}
              d={d}
              fill="none"
              stroke={fg}
              strokeWidth={strokeW}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          ))}
        </g>
      </svg>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 60%, ${background ?? p.bg} 100%)`,
          opacity: 0.6,
          pointerEvents: "none",
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  word: {
    type: "text-content",
    default: "LAUNCH",
    description: "Word",
  },
  count: {
    type: "number",
    default: 40,
    min: 10,
    max: 80,
    step: 1,
    description: "Lines",
    hiddenFromList: false,
  },
  sweep: {
    type: "number",
    default: 16,
    min: 0,
    max: 60,
    step: 1,
    description: "Sweep (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","word","count","sweep","accent","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "LAUNCH",
  count: 40,
  sweep: 16,
  accent: "#3B5BFD",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type LineReliefElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LineReliefBase>;

const LineReliefInner = forwardRef<
  HTMLDivElement,
  LineReliefElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LineRelief>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LineReliefBase
          {...(componentProps as unknown as ComponentProps<typeof LineReliefBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LineRelief = Interactive.withSchema({
  Component: LineReliefInner,
  componentName: "<LineRelief>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
